// ============================================================================
// 《Pocket Mirror: Goldenertraum》双层 RPG 状态机设置系统全局控制器 (Scheme A)
// 包含：一级 Scene_Menu、二级 Scene_Settings、高帧率平移动效与退出拦截控制器
// ============================================================================

window.__pmCloseSettingsToMenu = function(container) {
  if (!container) return;
  if (container.getAttribute('data-scene-transition') === 'closing') return;
  if (container.getAttribute('data-active-detail') !== 'true') return;

  container.setAttribute('data-scene-transition', 'closing');
  setTimeout(() => {
    container.setAttribute('data-active-detail', 'false');
    container.removeAttribute('data-scene-transition');
  }, 120);
};

window.__pmOpenSettingsDetail = function(container) {
  if (!container) return;
  container.removeAttribute('data-scene-transition');
  container.setAttribute('data-active-detail', 'true');
};

window.__pmTriggerModalExit = function(container, onComplete) {
  if (!container) {
    if (onComplete) onComplete();
    return;
  }
  if (container.getAttribute('data-modal-closing') === 'true') return;

  const backdrop = container.closest('.settings-modal-backdrop') || document.querySelector('.settings-modal-backdrop');
  if (backdrop) backdrop.setAttribute('data-modal-closing', 'true');
  container.setAttribute('data-modal-closing', 'true');

  // Zero artificial delay! Overlap visual snap-shut animation with base-ui destruction
  if (onComplete) onComplete();
};


// ============================================================================
// 《Pocket Mirror》界面语言双向切换系统 (Display Language Controller)
// 支持中英文实时无缝切换、状态双向感应与持久化
// ============================================================================
window.__pmLang = {
  get: function() {
    return localStorage.getItem('agy_display_language') || 'zh';
  },
  set: function(lang) {
    if (lang !== 'zh' && lang !== 'en') return;
    localStorage.setItem('agy_display_language', lang);
    this.apply(lang);
  },
  apply: function(lang) {
    lang = lang || this.get();
    const isZh = lang === 'zh';
    
    // 1. 同步补丁全局上下文开关
    if (window.__AG_PATCH_CTX__ && window.__AG_PATCH_CTX__.modules) {
      window.__AG_PATCH_CTX__.modules.i18n = isZh;
    }

    // 2. 文本节点与属性双向实时转换
    if (!isZh) {
      // 英文模式：断开汉化观察器，全面还原所有文本与属性
      if (window.__ag_i18n_observer) {
        try { window.__ag_i18n_observer.disconnect(); } catch(e) {}
      }
      if (window.__ag_orig_text_map) {
        const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
        while (walker.nextNode()) {
          const node = walker.currentNode;
          const rec = window.__ag_orig_text_map.get(node);
          if (rec && node.nodeValue === rec.lastVal) {
            node.nodeValue = rec.origRaw;
          }
        }
      }
      const attrNames = ['title', 'placeholder', 'aria-label'];
      const attrEls = document.querySelectorAll(
        '[data-ag-orig-title], [data-ag-orig-title-last], [data-ag-orig-placeholder], [data-ag-orig-placeholder-last], [data-ag-orig-aria-label], [data-ag-orig-aria-label-last]'
      );
      for (let i = 0; i < attrEls.length; i++) {
        const el = attrEls[i];
        for (let j = 0; j < attrNames.length; j++) {
          const attr = attrNames[j];
          const origAttr = 'data-ag-orig-' + attr;
          const lastAttr = origAttr + '-last';
          if (el.hasAttribute(origAttr) || el.hasAttribute(lastAttr)) {
            const savedOrig = el.getAttribute(origAttr);
            const savedLast = el.getAttribute(lastAttr);
            const cur = el.getAttribute(attr);
            if (savedOrig !== null && (savedLast === null || cur === savedLast)) {
              el.setAttribute(attr, savedOrig);
            }
            el.removeAttribute(origAttr);
            el.removeAttribute(lastAttr);
          }
        }
      }
    } else {
      // 中文模式：基于 i18n.json 词典全量翻译
      if (window.__ag_i18n_dict && window.__ag_orig_text_map) {
        const dict = window.__ag_i18n_dict;
        const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
        while (walker.nextNode()) {
          const node = walker.currentNode;
          const raw = node.nodeValue;
          if (!raw) continue;
          const trimmed = raw.trim();
          if (!trimmed) continue;
          let rep = dict[trimmed];
          if (!rep && trimmed.endsWith('.')) {
            const without = dict[trimmed.slice(0, -1)];
            if (without) rep = without.endsWith('。') ? without : without + '。';
          }
          if (typeof rep === 'string') {
            const nextVal = raw.replace(trimmed, rep);
            window.__ag_orig_text_map.set(node, { origRaw: raw, lastVal: nextVal });
            node.nodeValue = nextVal;
          }
        }
        const attrNames = ['title', 'placeholder', 'aria-label'];
        const allEls = document.querySelectorAll('[title], [placeholder], [aria-label]');
        for (let i = 0; i < allEls.length; i++) {
          const el = allEls[i];
          for (let j = 0; j < attrNames.length; j++) {
            const attr = attrNames[j];
            const cur = el.getAttribute(attr);
            if (cur && dict[cur.trim()]) {
              el.setAttribute('data-ag-orig-' + attr, cur);
              el.setAttribute('data-ag-orig-' + attr + '-last', dict[cur.trim()]);
              el.setAttribute(attr, dict[cur.trim()]);
            }
          }
        }
      }
      if (window.__ag_i18n_observer) {
        try {
          window.__ag_i18n_observer.observe(document.body, {
            childList: true,
            subtree: true,
            characterData: true,
            attributes: true,
            attributeFilter: ['title', 'aria-label', 'placeholder']
          });
        } catch(e) {}
      }
    }

    // 3. 更新设置界面所有自制组件文本与按钮状态
    this.updateUI(lang);
  },
  updateUI: function(lang) {
    lang = lang || this.get();
    const isZh = lang === 'zh';

    // 侧边栏指令项文本映射
    const labelMap = isZh ? {
      'settings-nav-item-General': '常规',
      'settings-nav-item-App': '应用',
      'settings-nav-item-Appearance': '外观',
      'settings-nav-item-Shortcuts': '快捷键',
      'settings-nav-item-Notifications': '通知',
      'settings-nav-item-Models': '模型',
      'settings-nav-item-Browser': '浏览器',
      'settings-nav-item-Hell Maiden': '项目',
      'settings-nav-item-Conversations': '对话'
    } : {
      'settings-nav-item-General': 'General',
      'settings-nav-item-App': 'App',
      'settings-nav-item-Appearance': 'Appearance',
      'settings-nav-item-Shortcuts': 'Shortcuts',
      'settings-nav-item-Notifications': 'Notifications',
      'settings-nav-item-Models': 'Models',
      'settings-nav-item-Browser': 'Browser',
      'settings-nav-item-Hell Maiden': 'Projects',
      'settings-nav-item-Conversations': 'Conversations'
    };

    Object.entries(labelMap).forEach(([testId, label]) => {
      const btn = document.querySelector(`[data-testid="${testId}"]`);
      if (btn) {
        const textNodes = Array.from(btn.childNodes).filter(n => n.nodeType === Node.TEXT_NODE);
        if (textNodes.length > 0) {
          textNodes[0].textContent = label;
        } else {
          btn.innerText = label;
        }
      }
    });

    // 4k 模式单选框图标补充
    const radios = document.querySelectorAll('#project4kMode [role="radio"]');
    radios.forEach(radio => {
      const text = radio.innerText || '';
      if ((text.includes('知识工作') || text.includes('Knowledge')) && !radio.querySelector('.pm-card-icon')) {
        const icon = document.createElement('span');
        icon.className = 'pm-card-icon';
        icon.innerText = '📄 ';
        radio.prepend(icon);
      } else if ((text.includes('软件工程') || text.includes('Software')) && !radio.querySelector('.pm-card-icon')) {
        const icon = document.createElement('span');
        icon.className = 'pm-card-icon';
        icon.innerText = '🛠️ ';
        radio.prepend(icon);
      }
    });

    // 左上角操作指引
    const cornerHints = document.querySelector('.pm-decor-corner-hints');
    if (cornerHints) {
      cornerHints.innerHTML = isZh
        ? '<div>Z / Enter 确定</div><div>X / ESC 返回/菜单</div><div>↑ ↓ ← → 选择</div><div>Q / W 切换标签</div>'
        : '<div>Z / Enter Confirm</div><div>X / ESC Back/Menu</div><div>↑ ↓ ← → Select</div><div>Q / W Switch Tab</div>';
    }
    const keyHints = document.querySelector('#pm-key-hints');
    if (keyHints) {
      keyHints.innerHTML = isZh
        ? '<div>Z / Enter 确定</div><div>X 返回菜单 / ESC 退出</div><div>↑ ↓ ← → 选择</div><div>Q / W 切换标签</div>'
        : '<div>Z / Enter Confirm</div><div>X Back to Menu / ESC Exit</div><div>↑ ↓ ← → Select</div><div>Q / W Switch Tab</div>';
    }

    // 底部数值栏
    const bottomStats = document.querySelector('.pm-decor-bottom-stats');
    if (bottomStats) {
      bottomStats.innerHTML = isZh
        ? '<div>小饰品: <span style="color:#ffffff; font-size:24px; font-weight:bold;">200</span></div><div>时间: <span style="color:#ffffff; font-size:24px; font-weight:bold;">00:55:27</span></div>'
        : '<div>Trinkets: <span style="color:#ffffff; font-size:24px; font-weight:bold;">200</span></div><div>Time: <span style="color:#ffffff; font-size:24px; font-weight:bold;">00:55:27</span></div>';
    }

    // 二级返回按钮提示
    const retBtn = document.querySelector('#pm-return-btn');
    if (retBtn) {
      retBtn.setAttribute('title', isZh ? '返回主菜单' : 'Back to Main Menu');
    }

    // HUD 快捷切换按钮高亮同步
    document.querySelectorAll('.pm-quick-lang-btn').forEach(b => {
      const bLang = b.getAttribute('data-lang');
      if (bLang === lang) {
        b.classList.add('active');
      } else {
        b.classList.remove('active');
      }
    });

    // 二级常规设置中的语言卡片同步
    const card = document.getElementById('pm-language-settings-card');
    if (card) {
      const title = card.querySelector('#pm-lang-card-title');
      if (title) title.textContent = isZh ? '显示语言 / Display Language' : 'Display Language / 显示语言';
      const desc = card.querySelector('#pm-lang-card-desc');
      if (desc) desc.textContent = isZh
        ? '选择界面的显示语言（支持实时切换中英文并持久化保存）'
        : 'Choose interface display language (real-time toggle with persistent state)';
      
      const zhBtn = card.querySelector('[data-lang="zh"]');
      const enBtn = card.querySelector('[data-lang="en"]');
      if (zhBtn && enBtn) {
        if (isZh) {
          zhBtn.classList.add('active');
          enBtn.classList.remove('active');
          const zhBadge = zhBtn.querySelector('.pm-lang-badge');
          if (zhBadge) zhBadge.textContent = '生效中';
          const enBadge = enBtn.querySelector('.pm-lang-badge');
          if (enBadge) enBadge.textContent = '切换';
        } else {
          zhBtn.classList.remove('active');
          enBtn.classList.add('active');
          const zhBadge = zhBtn.querySelector('.pm-lang-badge');
          if (zhBadge) zhBadge.textContent = 'Switch';
          const enBadge = enBtn.querySelector('.pm-lang-badge');
          if (enBadge) enBadge.textContent = 'Active';
        }
      }
    }
  }
};

(function() {
  function initPmSettingsController() {
    const m = document.querySelector('.settings-modal-container');
    if (!m) return;

    // 1. Initial State: Scene_Menu if not set
    if (!m.hasAttribute('data-active-detail')) {
      m.setAttribute('data-active-detail', 'false');
    }

    // 2. Mount Goldia decor layer
    let decor = m.querySelector('#goldia-decor-layer');
    if (!decor) {
      decor = document.createElement('div');
      decor.id = 'goldia-decor-layer';
      decor.style.cssText = 'position:absolute;inset:0;pointer-events:none;z-index:24;';
      decor.innerHTML = `
        <!-- 顶部王冠步行小人 -->
        <div class="pm-decor-crown-walker" style="position:absolute; top:64px; left:50%; transform:translateX(-50%); width:48px; height:58px; z-index:26; background:url('data:image/gif;base64,') center/contain no-repeat;"></div>

        <!-- Goldia 官方立绘 -->
        <div class="pm-decor-portrait" style="position:absolute; right:110px; bottom:0; width:430px; height:540px; background-image:url('data:image/png;base64,'); background-repeat:no-repeat; background-position:right bottom; background-size:430px 540px; pointer-events:none; z-index:10; filter:drop-shadow(0 0 16px rgba(0,0,0,0.85));"></div>

        <!-- 立绘旁专属 HUD -->
        <div class="pm-decor-hud" style="position:absolute; right:150px; bottom:175px; z-index:15; pointer-events:none; display:flex; flex-direction:column; align-items:flex-end;">
          <div style="font-family:'Cinzel', 'Noto Serif SC', serif; font-size:24px; color:#ffd700; text-shadow:0 0 8px #ff9800, 0 2px 4px #000; letter-spacing:2px; font-weight:bold;">G????!?</div>
                    </div>
          <!-- 快捷语言切换 -->
          <div class="pm-hud-lang-row" style="margin-top:10px; padding-top:8px; border-top:1px solid rgba(138,109,59,0.45); display:flex; align-items:center; justify-content:space-between; font-family:'Cinzel', 'Noto Serif SC', serif;">
            <span style="font-size:11px; color:#c4a872; display:flex; align-items:center; gap:4px;">🌐 语言:</span>
            <div style="display:flex; gap:6px;">
              <button type="button" class="pm-quick-lang-btn" data-lang="zh" style="background:rgba(45,18,36,0.75); border:1px solid rgba(138,109,59,0.5); border-radius:3px; color:#c4a872; font-family:'Cinzel', 'Noto Serif SC', serif; font-size:11px; padding:2px 8px; cursor:pointer;" title="切换至简体中文">中文</button>
              <button type="button" class="pm-quick-lang-btn" data-lang="en" style="background:rgba(45,18,36,0.75); border:1px solid rgba(138,109,59,0.5); border-radius:3px; color:#c4a872; font-family:'Cinzel', 'Noto Serif SC', serif; font-size:11px; padding:2px 8px; cursor:pointer;" title="Switch to English">EN</button>
            </div>
          </div>
        </div>
        </div>

        <!-- 左上角按键指引 -->
        <div class="pm-decor-corner-hints" style="position:absolute; top:36px; left:52px; font-family:'Noto Serif SC', serif; font-size:13px; color:#d0c8b6; z-index:26; line-height:1.6; text-shadow:0 2px 4px rgba(0,0,0,0.9); opacity:0.85;">
          <div>Z / Enter 确定</div>
          <div>X / ESC 返回/菜单</div>
          <div>↑ ↓ ← → 选择</div>
          <div>Q / W 切换标签</div>
        </div>

        <!-- 底部数值 -->
        <div class="pm-decor-bottom-stats" style="position:absolute; bottom:22px; left:0; width:100%; display:flex; justify-content:space-between; padding:0 240px; font-size:20px; color:#d0c8b6; z-index:26; font-family:'Cinzel', 'Noto Serif SC', serif; box-sizing:border-box; text-shadow:0 2px 4px rgba(0,0,0,0.9);">
          <div>小饰品: <span style="color:#ffffff; font-size:24px; font-weight:bold;">200</span></div>
          <div>时间: <span style="color:#ffffff; font-size:24px; font-weight:bold;">00:55:27</span></div>
        </div>
      `;
      m.appendChild(decor);
      // Bind HUD quick language buttons
      const hudLangRow = decor.querySelector('.pm-hud-lang-row');
      if (hudLangRow && !hudLangRow.__pm_bound) {
        hudLangRow.__pm_bound = true;
        hudLangRow.addEventListener('click', (e) => {
          const btn = e.target.closest('.pm-quick-lang-btn');
          if (btn) {
            e.preventDefault(); e.stopPropagation();
            const targetLang = btn.getAttribute('data-lang');
            if (targetLang && window.__pmLang) {
              window.__pmLang.set(targetLang);
            }
          }
        });
      }
    } else {
      // Ensure semantic classes on children
      const ch = decor.children;
      if (ch[0] && !ch[0].classList.contains('pm-decor-crown-walker')) ch[0].classList.add('pm-decor-crown-walker');
      if (ch[1] && !ch[1].classList.contains('pm-decor-portrait')) ch[1].classList.add('pm-decor-portrait');
      if (ch[2] && !ch[2].classList.contains('pm-decor-hud')) ch[2].classList.add('pm-decor-hud');
      if (ch[3] && !ch[3].classList.contains('pm-decor-corner-hints')) ch[3].classList.add('pm-decor-corner-hints');
      if (ch[4] && !ch[4].classList.contains('pm-decor-bottom-stats')) ch[4].classList.add('pm-decor-bottom-stats');
    }

    // 3. Ensure options frame
    if (!m.querySelector('#pm-options-frame')) {
      const frame = document.createElement('div');
      frame.id = 'pm-options-frame';
      m.appendChild(frame);
    }

    // 4. Ensure hints
    if (!m.querySelector('#pm-key-hints')) {
      const hints = document.createElement('div');
      hints.id = 'pm-key-hints';
      hints.innerHTML = '<div>Z / Enter 确定</div><div>X 返回菜单 / ESC 退出</div><div>↑ ↓ ← → 选择</div><div>Q / W 切换标签</div>';
      m.appendChild(hints);
    }

    // 5. Ensure return button in Scene_Settings
    if (!m.querySelector('#pm-return-btn')) {
      const retBtn = document.createElement('button');
      retBtn.id = 'pm-return-btn';
      retBtn.setAttribute('type', 'button');
      retBtn.setAttribute('title', '返回主菜单');
      retBtn.onclick = (e) => {
        if (e) { e.preventDefault(); e.stopPropagation(); }
        window.__pmCloseSettingsToMenu(m);
      };
      m.appendChild(retBtn);
    }

    // 6. Bind sidebar nav items
    const sidebar = m.querySelector('[data-testid="settings-sidebar"]');
    if (sidebar && !sidebar.__pm_bound) {
      sidebar.__pm_bound = true;
      sidebar.addEventListener('click', (e) => {
        const navBtn = e.target.closest('button[data-testid^="settings-nav-item"]');
        if (navBtn) {
          window.__pmOpenSettingsDetail(m);
          if (window.__pmLang) { window.__pmLang.updateUI(); }
          ensureLanguageCard();
        }
      });
    }

    // 7. Intercept native close button for smooth closing animation
    const closeBtn = m.querySelector(':is(button[aria-label="关闭"], button[aria-label="Close"], button:first-child)');
    if (closeBtn && !closeBtn.__pmExitIntercepted) {
      closeBtn.__pmExitIntercepted = true;
      closeBtn.addEventListener('click', (e) => {
        if (closeBtn.__pmRealClick) return;
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();
        window.__pmTriggerModalExit(m, () => {
          closeBtn.__pmRealClick = true;
          closeBtn.click();
        });
      }, true);
    }

    // 8. Intercept backdrop clicks
    const backdrop = m.closest('.settings-modal-backdrop') || document.querySelector('.settings-modal-backdrop');
    if (backdrop && !backdrop.__pmBackdropBound) {
      backdrop.__pmBackdropBound = true;
      backdrop.addEventListener('click', (e) => {
        if (e.target === backdrop) {
          e.preventDefault();
          e.stopPropagation();
          e.stopImmediatePropagation();
          window.__pmTriggerModalExit(m, () => {
            if (closeBtn) {
              closeBtn.__pmRealClick = true;
              closeBtn.click();
            }
          });
        }
      }, true);
    }

    
    function ensureLanguageCard() {
      const container = m.querySelector('.p-6.flex.flex-col.gap-4.w-full.max-w-2xl.mx-auto');
      if (!container) return;

      let card = document.getElementById('pm-language-settings-card');
      if (!card) {
        card = document.createElement('div');
        card.id = 'pm-language-settings-card';
        card.className = 'pm-settings-card pm-language-card';
        const lang = window.__pmLang ? window.__pmLang.get() : 'zh';
        const isZh = lang === 'zh';
        card.innerHTML = `
          <div class="pm-card-inner">
            <div class="pm-card-header">
              <div class="pm-card-title-group">
                <span class="pm-card-title-icon">🌐</span>
                <span class="pm-card-title" id="pm-lang-card-title">${isZh ? '显示语言 / Display Language' : 'Display Language / 显示语言'}</span>
              </div>
              <div class="pm-card-desc" id="pm-lang-card-desc">${isZh ? '选择界面的显示语言（支持实时切换中英文并持久化保存）' : 'Choose interface display language (real-time toggle with persistent state)'}</div>
            </div>
            <div class="pm-lang-toggle-group">
              <button type="button" class="pm-lang-btn ${isZh ? 'active' : ''}" data-lang="zh">
                <div class="pm-lang-btn-left">
                  <span class="pm-lang-btn-icon">🇨🇳</span>
                  <span class="pm-lang-btn-label">简体中文</span>
                </div>
                <span class="pm-lang-badge">${isZh ? '生效中' : '切换'}</span>
              </button>
              <button type="button" class="pm-lang-btn ${!isZh ? 'active' : ''}" data-lang="en">
                <div class="pm-lang-btn-left">
                  <span class="pm-lang-btn-icon">🇬🇧</span>
                  <span class="pm-lang-btn-label">English</span>
                </div>
                <span class="pm-lang-badge">${!isZh ? 'Active' : 'Switch'}</span>
              </button>
            </div>
          </div>
        `;
        card.addEventListener('click', (e) => {
          const btn = e.target.closest('.pm-lang-btn');
          if (btn) {
            e.preventDefault(); e.stopPropagation();
            const targetLang = btn.getAttribute('data-lang');
            if (targetLang && window.__pmLang) {
              window.__pmLang.set(targetLang);
            }
          }
        });
        container.prepend(card);
      }
    }

    function updateLabels() {
      const labelMap = {
        'settings-nav-item-General': '常规',
        'settings-nav-item-App': '应用',
        'settings-nav-item-Appearance': '外观',
        'settings-nav-item-Shortcuts': '快捷键',
        'settings-nav-item-Notifications': '通知',
        'settings-nav-item-Models': '模型',
        'settings-nav-item-Browser': '浏览器',
        'settings-nav-item-Hell Maiden': '项目',
        'settings-nav-item-Conversations': '对话'
      };

      Object.entries(labelMap).forEach(([testId, label]) => {
        const btn = document.querySelector(`[data-testid="${testId}"]`);
        if (btn) {
          const textNodes = Array.from(btn.childNodes).filter(n => n.nodeType === Node.TEXT_NODE);
          if (textNodes.length > 0) {
            if (textNodes[0].textContent !== label) {
              textNodes[0].textContent = label;
            }
          } else if (btn.innerText !== label) {
            btn.innerText = label;
          }
        }
      });

      const radios = document.querySelectorAll('#project4kMode [role="radio"]');
      radios.forEach(radio => {
        const text = radio.innerText || '';
        if (text.includes('知识工作') && !radio.querySelector('.pm-card-icon')) {
          const icon = document.createElement('span');
          icon.className = 'pm-card-icon';
          icon.innerText = '📄 ';
          radio.prepend(icon);
        } else if (text.includes('软件工程') && !radio.querySelector('.pm-card-icon')) {
          const icon = document.createElement('span');
          icon.className = 'pm-card-icon';
          icon.innerText = '🛠️ ';
          radio.prepend(icon);
        }
      });
    }

    if (window.__pmLang) { window.__pmLang.updateUI(); }
    ensureLanguageCard();
  }

  // 极轻量节流 Observer：只在检测到设置弹窗实际存在或发生变化时触发，彻底避免常规聊天与打字触发无谓扫描
  let pmObserverRaf = null;
  const observer = new MutationObserver((mutations) => {
    let relevant = false;
    for (let i = 0; i < mutations.length; i++) {
      const m = mutations[i];
      if (m.target && m.target.closest && m.target.closest('.settings-modal-container')) {
        relevant = true;
        break;
      }
      const added = m.addedNodes;
      for (let j = 0; j < added.length; j++) {
        const node = added[j];
        if (node.nodeType === 1 && (node.classList?.contains('settings-modal-container') || (node.querySelector && node.querySelector('.settings-modal-container')))) {
          relevant = true;
          break;
        }
      }
      if (relevant) break;
    }
    if (!relevant) return;

    if (pmObserverRaf) return;
    pmObserverRaf = requestAnimationFrame(() => {
      pmObserverRaf = null;
      if (document.querySelector('.settings-modal-container')) {
        initPmSettingsController();
      }
    });
  });
  observer.observe(document.body, { childList: true, subtree: true });

  window.addEventListener('keydown', (e) => {
    const m = document.querySelector('.settings-modal-container');
    if (!m) return;

    if (e.key === 'Escape') {
      // ESC unconditionally closes the entire settings modal instantly to restore workspace
      e.preventDefault();
      e.stopPropagation();
      e.stopImmediatePropagation();
      const closeBtn = m.querySelector(':is(button[aria-label="关闭"], button[aria-label="Close"], button:first-child)');
      window.__pmTriggerModalExit(m, () => {
        if (closeBtn) {
          closeBtn.__pmRealClick = true;
          closeBtn.click();
        }
      });
    } else if (e.key === 'x' || e.key === 'X') {
      const isDetail = m.getAttribute('data-active-detail') === 'true';
      if (isDetail) {
        // X key returns to primary menu
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();
        window.__pmCloseSettingsToMenu(m);
      } else {
        // At primary menu, X key exits
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();
        const closeBtn = m.querySelector(':is(button[aria-label="关闭"], button[aria-label="Close"], button:first-child)');
        window.__pmTriggerModalExit(m, () => {
          if (closeBtn) {
            closeBtn.__pmRealClick = true;
            closeBtn.click();
          }
        });
      }
    }
  }, true);

  initPmSettingsController();
  // Apply saved display language on startup
  try {
    if (window.__pmLang) {
      const savedLang = window.__pmLang.get();
      if (savedLang === 'en') {
        window.__pmLang.apply('en');
      }
    }
  } catch(e) {}
})();

// ============================================================================
// 3. 《Pocket Mirror: Goldenertraum》恶魔剧场舞台帷幕 (实时可调参版 v12)
// ============================================================================
(function initPocketMirrorTheatreCurtains() {
  let overlay = document.getElementById('antigravity-curtain-overlay');
  if (!overlay) {
    overlay = document.createElement('div');
    overlay.id = 'antigravity-curtain-overlay';
    overlay.setAttribute('aria-hidden', 'true');
    document.body.appendChild(overlay);
  }

  let transition = document.getElementById('antigravity-curtain-transition');
  if (!transition) {
    transition = document.createElement('div');
    transition.id = 'antigravity-curtain-transition';
    transition.setAttribute('aria-hidden', 'true');
    transition.innerHTML = `
      <div class="agy-curtain-half-left"></div>
      <div class="agy-curtain-half-right"></div>
      <div class="agy-curtain-frame"></div>
    `;
    document.body.appendChild(transition);
  }

  // 显存预热
  const imgAssets = ["data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,"];
  imgAssets.forEach(src => {
    const img = new Image();
    img.src = src;
    if (img.decode) img.decode().catch(() => {});
  });

  // 音效预加载
  let sndOpen = null;
  let sndClose = null;
  try {
    sndOpen = new Audio("data:audio/ogg;base64,");
    sndClose = new Audio("data:audio/ogg;base64,");
    sndOpen.volume = 0.65;
    sndClose.volume = 0.65;
    sndOpen.load();
    sndClose.load();
  } catch (e) {
    console.warn('[Curtains] Audio init failed:', e);
  }

  // 侧栏智能避让（rAF 节流，避免高频滑动卡顿）
  let lastInSidebar = false;
  let lastInRight = false;
  let mouseMoveRaf = null;
  function onMouseMove(e) {
    if (mouseMoveRaf) return;
    const clientX = e.clientX;
    const innerWidth = window.innerWidth;
    mouseMoveRaf = requestAnimationFrame(() => {
      mouseMoveRaf = null;
      const inSidebar = clientX <= 360;
      if (inSidebar !== lastInSidebar) {
        lastInSidebar = inSidebar;
        overlay.classList.toggle('hover-sidebar', inSidebar);
      }
      const inRight = clientX >= (innerWidth - 220);
      if (inRight !== lastInRight) {
        lastInRight = inRight;
        overlay.classList.toggle('hover-right', inRight);
      }
    });
  }
  window.addEventListener('mousemove', onMouseMove, { passive: true });

  // ==========================================================================
  // 🎛️ 运行时配置与持久化存储
  // ==========================================================================
  const defaultConfig = {
    closeDuration: 360,
    holdDuration: 40,
    openDuration: 360,
    soundVolume: 65
  };

  let config = Object.assign({}, defaultConfig);
  try {
    const saved = localStorage.getItem('agy_curtain_config');
    if (saved) {
      Object.assign(config, JSON.parse(saved));
    }
  } catch (e) {}

  function applyConfig() {
    document.documentElement.style.setProperty('--curtain-close-dur', (config.closeDuration / 1000) + 's');
    document.documentElement.style.setProperty('--curtain-open-dur', (config.openDuration / 1000) + 's');
    if (sndOpen) sndOpen.volume = config.soundVolume / 100;
    if (sndClose) sndClose.volume = config.soundVolume / 100;
  }
  applyConfig();

  // 核心转场调度函数
  let isTransitioning = false;
  function runTheatreTransition(onCurtainFullyClosed) {
    if (isTransitioning) return;
    isTransitioning = true;

    transition.className = 'active closing';

    if (sndClose && config.soundVolume > 0) {
      try {
        sndClose.currentTime = 0;
        sndClose.play().catch(() => {});
      } catch (_) {}
    }

    setTimeout(() => {
      transition.className = 'active closed-hold';

      if (typeof onCurtainFullyClosed === 'function') {
        try {
          onCurtainFullyClosed();
        } catch (err) {
          console.error('[Curtains] Backend switch error:', err);
        }
      }

      setTimeout(() => {
        if (sndOpen && config.soundVolume > 0) {
          try {
            sndOpen.currentTime = 0;
            sndOpen.play().catch(() => {});
          } catch (_) {}
        }

        transition.className = 'active opening';

        setTimeout(() => {
          transition.className = '';
          isTransitioning = false;
        }, config.openDuration + 30);

      }, config.holdDuration);

    }, config.closeDuration);
  }

  window.__antigravityTriggerCurtainTransition = runTheatreTransition;

  // 侧栏点击拦截与并发转场
  function onSidebarClick(e) {
    const row = e.target.closest(':is([data-testid="conversation-row-sidebar"], .agy-sidebar-row):not(button[data-testid="project-header"]):not(button[data-project-card="true"])');
    if (!row) return;

    const isAlreadySelected = row.getAttribute('data-selected') === 'true' ||
                              row.getAttribute('data-active') === 'true' ||
                              row.getAttribute('aria-selected') === 'true';
    if (isAlreadySelected) return;

    runTheatreTransition();
  }
  document.addEventListener('click', onSidebarClick, true);

  // ==========================================================================
  // 🎛️ 挂载实时调参控制台 UI
  // ==========================================================================
  let tuneBtn = document.getElementById('agy-curtain-tune-btn');
  if (!tuneBtn) {
    tuneBtn = document.createElement('div');
    tuneBtn.id = 'agy-curtain-tune-btn';
    tuneBtn.title = '打开恶魔剧场帷幕调参控制台';
    tuneBtn.innerHTML = '🎭';
    document.body.appendChild(tuneBtn);
  }

  let tunePanel = document.getElementById('agy-curtain-tune-panel');
  if (!tunePanel) {
    tunePanel = document.createElement('div');
    tunePanel.id = 'agy-curtain-tune-panel';
    tunePanel.innerHTML = `
      <div class="agy-tune-header">
        <div class="agy-tune-title"><span>🎭</span> 恶魔剧场帷幕实时调参台</div>
        <div class="agy-tune-close" id="agy-tune-close-btn">✕</div>
      </div>

      <div class="agy-tune-row">
        <div class="agy-tune-label-bar">
          <span>闭幕速度 (Close)</span>
          <span class="agy-tune-val" id="val-close">${config.closeDuration}ms</span>
        </div>
        <input type="range" class="agy-tune-slider" id="slider-close" min="100" max="1000" step="20" value="${config.closeDuration}">
      </div>

      <div class="agy-tune-row">
        <div class="agy-tune-label-bar">
          <span>中央停顿 (Hold)</span>
          <span class="agy-tune-val" id="val-hold">${config.holdDuration}ms</span>
        </div>
        <input type="range" class="agy-tune-slider" id="slider-hold" min="0" max="800" step="20" value="${config.holdDuration}">
      </div>

      <div class="agy-tune-row">
        <div class="agy-tune-label-bar">
          <span>开幕速度 (Open)</span>
          <span class="agy-tune-val" id="val-open">${config.openDuration}ms</span>
        </div>
        <input type="range" class="agy-tune-slider" id="slider-open" min="100" max="1000" step="20" value="${config.openDuration}">
      </div>

      <div class="agy-tune-row">
        <div class="agy-tune-label-bar">
          <span>音效音量 (Volume)</span>
          <span class="agy-tune-val" id="val-vol">${config.soundVolume}%</span>
        </div>
        <input type="range" class="agy-tune-slider" id="slider-vol" min="0" max="100" step="5" value="${config.soundVolume}">
      </div>

      <div class="agy-tune-presets">
        <button class="agy-tune-preset-btn" id="preset-swift">⚡ 极速流 (200ms)</button>
        <button class="agy-tune-preset-btn" id="preset-golden">✨ 黄金推荐 (360ms)</button>
        <button class="agy-tune-preset-btn" id="preset-classic">🎪 原版40帧 (670ms)</button>
        <button class="agy-tune-preset-btn" id="preset-rebound">🪞 触碰即开 (0ms停顿)</button>
      </div>

      <div class="agy-tune-actions">
        <button class="agy-tune-action-btn agy-btn-test" id="agy-btn-run-test">▶ 一键测试播放</button>
      </div>
    `;
    document.body.appendChild(tunePanel);
  }

  // 事件绑定
  tuneBtn.onclick = () => {
    tunePanel.classList.toggle('visible');
  };
  document.getElementById('agy-tune-close-btn').onclick = () => {
    tunePanel.classList.remove('visible');
  };

  const sClose = document.getElementById('slider-close');
  const sHold = document.getElementById('slider-hold');
  const sOpen = document.getElementById('slider-open');
  const sVol = document.getElementById('slider-vol');

  function saveConfig() {
    try {
      localStorage.setItem('agy_curtain_config', JSON.stringify(config));
    } catch (e) {}
  }

  sClose.oninput = (e) => {
    config.closeDuration = parseInt(e.target.value);
    document.getElementById('val-close').innerText = config.closeDuration + 'ms';
    applyConfig();
    saveConfig();
  };

  sHold.oninput = (e) => {
    config.holdDuration = parseInt(e.target.value);
    document.getElementById('val-hold').innerText = config.holdDuration + 'ms';
    applyConfig();
    saveConfig();
  };

  sOpen.oninput = (e) => {
    config.openDuration = parseInt(e.target.value);
    document.getElementById('val-open').innerText = config.openDuration + 'ms';
    applyConfig();
    saveConfig();
  };

  sVol.oninput = (e) => {
    config.soundVolume = parseInt(e.target.value);
    document.getElementById('val-vol').innerText = config.soundVolume + '%';
    applyConfig();
    saveConfig();
  };

  // 预设按钮
  function setPreset(cDur, hDur, oDur) {
    config.closeDuration = cDur;
    config.holdDuration = hDur;
    config.openDuration = oDur;
    sClose.value = cDur;
    sHold.value = hDur;
    sOpen.value = oDur;
    document.getElementById('val-close').innerText = cDur + 'ms';
    document.getElementById('val-hold').innerText = hDur + 'ms';
    document.getElementById('val-open').innerText = oDur + 'ms';
    applyConfig();
    saveConfig();
    runTheatreTransition();
  }

  document.getElementById('preset-swift').onclick = () => setPreset(200, 0, 200);
  document.getElementById('preset-golden').onclick = () => setPreset(360, 40, 360);
  document.getElementById('preset-classic').onclick = () => setPreset(670, 200, 670);
  document.getElementById('preset-rebound').onclick = () => setPreset(320, 0, 320);

  // 一键试运行
  document.getElementById('agy-btn-run-test').onclick = () => {
    runTheatreTransition();
  };

  if (typeof ctx !== 'undefined' && ctx.onCleanup) {
    ctx.onCleanup(() => {
      window.removeEventListener('mousemove', onMouseMove);
      document.removeEventListener('click', onSidebarClick, true);
      if (overlay) overlay.remove();
      if (transition) transition.remove();
      if (tuneBtn) tuneBtn.remove();
      if (tunePanel) tunePanel.remove();
    });
  }
  console.log('[Curtains] Live Tuning Console v12 mounted!');
})();
